model Ball {
  id: ID
  x: Number
  y: Number
  vx: Number
  vy: Number
  r: Number
}

component BallSimulation {
  state balls: Ball[] = []
  state paused = false
  state frames = 0
  ref canvas
  ref animationId

  fn initBalls {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push({
        id: crypto.randomUUID(),
        x: Math.random() * 380 + 10,
        y: Math.random() * 280 + 10,
        vx: Math.random() * 4 - 2,
        vy: Math.random() * 4 - 2,
        r: 10
      })
    }
    frames = 0
  }

  fn addBall {
    balls.push({
      id: crypto.randomUUID(),
      x: Math.random() * 380 + 10,
      y: Math.random() * 280 + 10,
      vx: Math.random() * 4 - 2,
      vy: Math.random() * 4 - 2,
      r: 10
    })
  }

  fn togglePause {
    paused = !paused
  }

  fn reset {
    paused = false
    initBalls()
  }

  fn updatePhysics {
    const w = 400, h = 300

    // Aplicar gravedad
    for b in balls {
      b.vy += 0.2
    }

    // Actualizar posiciones
    for b in balls {
      b.x += b.vx
      b.y += b.vy
    }

    // Rebote contra bordes
    for b in balls {
      if b.x - b.r < 0 {
        b.x = b.r
        b.vx = -b.vx
      }
      if b.x + b.r > w {
        b.x = w - b.r
        b.vx = -b.vx
      }
      if b.y - b.r < 0 {
        b.y = b.r
        b.vy = -b.vy
      }
      if b.y + b.r > h {
        b.y = h - b.r
        b.vy = -b.vy
      }
    }

    // Colisiones elásticas
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const b1 = balls[i]
        const b2 = balls[j]
        const dx = b2.x - b1.x
        const dy = b2.y - b1.y
        const dist = Math.sqrt(dx * dx + dy * dy)

        if dist < b1.r + b2.r {
          // Intercambiar velocidades
          const temp_vx = b1.vx
          const temp_vy = b1.vy
          b1.vx = b2.vx
          b1.vy = b2.vy
          b2.vx = temp_vx
          b2.vy = temp_vy

          // Separar para evitar solapamiento
          const overlap = (b1.r + b2.r - dist) / 2 + 1
          const angle = Math.atan2(dy, dx)
          b1.x -= overlap * Math.cos(angle)
          b1.y -= overlap * Math.sin(angle)
          b2.x += overlap * Math.cos(angle)
          b2.y += overlap * Math.sin(angle)
        }
      }
    }
  }

  fn draw {
    const ctx = canvas.getContext("2d")
    ctx.fillStyle = "#f5f5f5"
    ctx.fillRect(0, 0, 400, 300)

    ctx.strokeStyle = "#999"
    ctx.lineWidth = 1
    ctx.strokeRect(0, 0, 400, 300)

    for b in balls {
      ctx.fillStyle = "#e11d48"
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn animate {
    if !paused {
      updatePhysics()
      frames++
    }
    draw()
    animationId = requestAnimationFrame(animate)
  }

  mount {
    initBalls()
    draw()
    animationId = requestAnimationFrame(animate)
    cleanup {
      if animationId {
        cancelAnimationFrame(animationId)
      }
    }
  }

  column gap=4 pad=4 {
    row gap=2 {
      button "Agregar" primary -> addBall()
      button (paused ? "Reanudar" : "Pausar") primary -> togglePause()
      button "Reiniciar" primary -> reset()
    }
    row gap=4 {
      text `Pelotas: ${balls.length}`
      text `Cuadros: ${frames}`
    }
    canvas id="sim" ref=canvas width=400 height=300 style="border: 1px solid #ddd;"
  }
}

