export interface Ball {
  x: number
  y: number
  vx: number
  vy: number
  r: number
}

const GRAVITY = 0.2
const WIDTH = 400
const HEIGHT = 300

export function step(balls: Ball[]) {
  // Apply gravity
  for (const ball of balls) {
    ball.vy += GRAVITY
  }

  // Bounce off edges
  for (const ball of balls) {
    ball.x += ball.vx
    ball.y += ball.vy

    if (ball.x - ball.r < 0) {
      ball.x = ball.r
      ball.vx = -ball.vx
    }
    if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r
      ball.vx = -ball.vx
    }
    if (ball.y - ball.r < 0) {
      ball.y = ball.r
      ball.vy = -ball.vy
    }
    if (ball.y + ball.r > HEIGHT) {
      ball.y = HEIGHT - ball.r
      ball.vy = -ball.vy
    }
  }

  // Collision detection and elastic collision
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const b1 = balls[i]
      const b2 = balls[j]
      const dx = b2.x - b1.x
      const dy = b2.y - b1.y
      const dist = Math.sqrt(dx * dx + dy * dy)
      const minDist = b1.r + b2.r

      if (dist < minDist) {
        // Swap velocities for elastic collision
        [b1.vx, b2.vx] = [b2.vx, b1.vx]
        [b1.vy, b2.vy] = [b2.vy, b1.vy]

        // Separate balls to avoid overlap
        const overlap = minDist - dist
        const angle = Math.atan2(dy, dx)
        const moveX = (overlap / 2) * Math.cos(angle)
        const moveY = (overlap / 2) * Math.sin(angle)

        b1.x -= moveX
        b1.y -= moveY
        b2.x += moveX
        b2.y += moveY
      }
    }
  }
}

export function draw(canvas: HTMLCanvasElement, balls: Ball[]) {
  const ctx = canvas.getContext("2d")!
  ctx.clearRect(0, 0, WIDTH, HEIGHT)

  for (const ball of balls) {
    ctx.beginPath()
    ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2)
    ctx.fillStyle = "#3b82f6"
    ctx.fill()
    ctx.strokeStyle = "#1e40af"
    ctx.lineWidth = 2
    ctx.stroke()
  }
}

