}

use "date-fns" { format, parse as parseDate }

const TRAVELERS = [
  { id: "1", name: "Ana Rojas", country: "Perú", city: "Lima", arrival: parseDate("2026-03-12", "yyyy-MM-dd", new Date()), budget: 1200 },
  { id: "2", name: "Bruno Díaz", country: "México", city: "Oaxaca", arrival: parseDate("2026-01-05", "yyyy-MM-dd", new Date()), budget: 850 },
  { id: "3", name: "Carla Gómez", country: "Perú", city: "Cusco", arrival: parseDate("2026-02-20", "yyyy-MM-dd", new Date()), budget: 2300 },
  { id: "4", name: "Diego Silva", country: "Chile", city: "Valparaíso", arrival: parseDate("2026-04-02", "yyyy-MM-dd", new Date()), budget: 640 },
  { id: "5", name: "Elena Ruiz", country: "México", city: "Mérida", arrival: parseDate("2026-03-01", "yyyy-MM-dd", new Date()), budget: 1500 },
  { id: "6", name: "Facundo Paz", country: "Argentina", city: "Salta", arrival: parseDate("2026-02-11", "yyyy-MM-dd", new Date()), budget: 990 },
  { id: "7", name: "Gabriela Luna", country: "Chile", city: "Santiago", arrival: parseDate("2026-01-28", "yyyy-MM-dd", new Date()), budget: 1750 },
  { id: "8", name: "Hugo Vera", country: "Argentina", city: "Mendoza", arrival: parseDate("2026-03-30", "yyyy-MM-dd", new Date()), budget: 1100 }
]

fn getInitials(name) {
  const parts = name.split(" ")
  return (parts[0][0] + parts[1][0]).toUpperCase()
}

fn getColorForName(name) {
  const colors = ["#e11d48", "#0891b2", "#7c3aed", "#ea580c", "#16a34a", "#2563eb", "#db2777", "#b91c1c"]
  let hash = 0
  for (let i = 0; i < name.length; i++) {
    hash = name.charCodeAt(i) + ((hash << 5) - hash)
  }
  return colors[Math.abs(hash) % colors.length]
}

fn formatBudget(amount) {
  return "US$ " + new Intl.NumberFormat("es-AR", { style: "decimal", minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(amount)
}

fn formatArrivalDate(date) {
  return format(date, "dd/MM/yyyy")
}

component TravelerCard(traveler: Traveler) {
  const initials = getInitials(traveler.name)
  const bgColor = getColorForName(traveler.name)

  column gap=3 pad=3 {
    row gap=3 align=center {
      card style={`width: 50px; height: 50px; background-color: ${bgColor}; display: flex; align-items: center; justify-content: center;`} {
        text initials bold style="color: white; font-size: 14px;"
      }
      column gap=1 {
        link traveler.name to={`/viajero/${traveler.id}`}
        text `${traveler.city}, ${traveler.country}` small muted
      }
    }
    text `Llega el ${formatArrivalDate(traveler.arrival)}` small muted
    text formatBudget(traveler.budget) small
  }
